"use client";
/* Sheep, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Sheep(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("sheep"); }, []);
  return React.createElement("piix-pal", { "pal": "sheep", ...piixAttrs(props) });
}

export default Sheep;
